param([string]$FinalInputPath="data\research\v57\final_input.csv",[double]$LongFraction=.20,[double]$TransactionCostBps=5,[ValidateSet("real","external_unverified","synthetic","demo","test")][string]$Provenance="external_unverified")
$ErrorActionPreference="Stop";Set-Location(Resolve-Path(Join-Path $PSScriptRoot ".."));$env:FINAI_V57_INPUT_PATH=$FinalInputPath;$env:FINAI_V57_LONG_FRACTION=$LongFraction.ToString([Globalization.CultureInfo]::InvariantCulture);$env:FINAI_V57_COST_BPS=$TransactionCostBps.ToString([Globalization.CultureInfo]::InvariantCulture);$env:FINAI_V57_PROVENANCE=$Provenance
